module star_wars_ordering (\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [1:0] q_type,\n    input wire [4:0] x,\n    output reg [4:0] result,\n    output reg done\n);\n    // Parameters\n    localparam [4:0] MAX_MOVIES = 5'd16;\n    localparam [5:0] MAX_OPS = 6'd64;\n    \n    // State declarations\n    localparam [1:0] IDLE = 2'd0;\n    localparam [1:0] EXECUTE = 2'd1;\n    localparam [1:0] COMPLETE = 2'd2;\n    \n    // Internal registers\n    reg [4:0] plot_order [0:15];  // 16 entries for movies\n    reg [4:0] creation_count;\n    reg [5:0] op_count;\n    reg [1:0] state;\n    \n    // Loop variable\n    integer i;\n    \n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            // Reset all registers\n            for (i = 0; i < 16; i = i+1) begin\n                plot_order[i] <= 5'd0;\n            end\n            creation_count <= 5'd0;\n            op_count <= 6'd0;\n            result <= 5'd0;\n            done <= 1'b0;\n            state <= IDLE;\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start && (op_count < MAX_OPS)) begin\n                        op_count <= op_count + 6'd1;\n                        state <= EXECUTE;\n                    end\n                end\n                \n                EXECUTE: begin\n                    if (q_type == 2'd1) begin  // Insert\n                        if ((creation_count < MAX_MOVIES) && (x >= 5'd1) && (x <= (creation_count + 5'd1))) begin\n                            // Shift elements\n                            for (i = MAX_MOVIES-1; i > x-1; i = i-1) begin\n                                if (i <= creation_count) begin\n                                    plot_order[i] <= plot_order[i-1];\n                                end\n                            end\n                            // Insert new movie\n                            plot_order[x-1] <= creation_count + 5'd1;\n                            creation_count <= creation_count + 5'd1;\n                        end\n                    end else if (q_type == 2'd2) begin  // Query\n                        if ((x >= 5'd1) && (x <= creation_count)) begin\n                            result <= plot_order[x-1];\n                        end\n                    end\n                    state <= COMPLETE;\n                end\n                \n                COMPLETE: begin\n                    done <= 1'b1;\n                    state <= IDLE;\n                end\n                \n                default: state <= IDLE;\n            endcase\n        end\n    end\nendmodule